##############################################################################
# Runs the TrustZone secure stack services against a live security unit.
#
# The services are non-secure-callable and dereference a thread control block
# pointer that the non-secure world supplies, so whether they refuse a pointer
# into secure memory can only be shown with the security extension active. This
# check builds the Cortex-M33 GNU port's secure stack services with -mcmse into a
# bare-metal secure image and runs it on the emulator's MPS2 AN505 board.
#
#     scripts/check_trustzone_secure_stack.sh
#
# Environment:
#     CROSS_CC   arm-none-eabi C compiler; defaults to arm-none-eabi-gcc.
#     QEMU       Arm system emulator; defaults to qemu-system-arm.
#
# Exit status is 0 when the image runs and every expectation holds, 1 when an
# expectation fails, and 0 with a notice when the tools are absent, so that a
# machine without a cross toolchain does not fail the build.

set -u

CC="${CROSS_CC:-arm-none-eabi-gcc}"
QEMU_BIN="${QEMU:-qemu-system-arm}"
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
SRC="$ROOT/test/tx/trustzone/threadx_trustzone_secure_stack_test.c"
PORT="$ROOT/ports/cortex_m33/gnu"

for tool in "$CC" "$QEMU_BIN"; do
    if ! command -v "$tool" >/dev/null 2>&1 && [ ! -x "$tool" ]; then
        echo "Skipping: $tool not found."
        echo "  Needs an arm-none-eabi toolchain and qemu-system-arm."
        exit 0
    fi
done

work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

# The image runs from the first SSRAM's secure alias and keeps its data in the
# lower half of the second SSRAM, which the attribution unit leaves secure. The
# upper half is the test's non-secure region. The linker places the secure
# gateway veneers only at a fixed address.
cat > "$work/image.ld" <<'LINKER'
MEMORY
{
  SCODE (rx) : ORIGIN = 0x10000000, LENGTH = 0x000F0000
  SDATA (rw) : ORIGIN = 0x28000000, LENGTH = 0x00100000
}
ENTRY(test_reset_handler)
SECTIONS
{
  .vectors : { KEEP(*(.vectors)) } > SCODE
  .text : { *(.text*) *(.rodata*) . = ALIGN(4); } > SCODE
  .ARM.exidx : { *(.ARM.exidx*) } > SCODE
  __etext = .;
  .data : AT(__etext) { __data_start__ = .; *(.data*) . = ALIGN(4); __data_end__ = .; } > SDATA
  .bss (NOLOAD) : { __bss_start__ = .; *(.bss*) *(COMMON) . = ALIGN(4); __bss_end__ = .; } > SDATA
  .heap (NOLOAD) : { . = ALIGN(8); end = .; . = . + 0x8000; } > SDATA
  .stack (NOLOAD) : { . = ALIGN(8); . = . + 0x4000; __stack_top__ = .; } > SDATA
}
LINKER

"$CC" -mcpu=cortex-m33 -mthumb -mcmse -O1 -std=gnu99 -Wall -Wextra -Werror \
      -nostartfiles --specs=rdimon.specs -T "$work/image.ld" \
      -Wl,--section-start=.gnu.sgstubs=0x100F0000 -Wl,--no-warn-rwx-segments \
      -I"$PORT/inc" -I"$ROOT/common/inc" \
      -o "$work/secure_stack_test.elf" "$SRC" "$PORT/src/tx_thread_secure_stack.c" || {
    echo "FAIL: the TrustZone secure stack test image did not build."
    exit 1
}

output="$(timeout 60 "$QEMU_BIN" -M mps2-an505 -nographic \
          -semihosting-config enable=on,target=native \
          -kernel "$work/secure_stack_test.elf" 2>/dev/null)"
status=$?
echo "$output"

if [ $status -ne 0 ] || ! echo "$output" | grep -q "SUCCESS!"; then
    echo "FAIL: the TrustZone secure stack test did not report success."
    exit 1
fi
exit 0
